/**
 * Trusted verification harness executed inside the isolated Docker sandbox.
 * The command is a fixed preset; the harness source is generated by Transactra
 * and never influenced by agent output.
 */
export const VERIFY_HARNESS_FILENAME = "transactra-verify.mjs";
export const VERIFY_PRESET = "transactra-verify";

export const VERIFY_HARNESS_SOURCE = `import { readdirSync, readFileSync } from "node:fs";
import { join, relative, extname } from "node:path";
import { spawnSync } from "node:child_process";

const root = process.cwd();
const MAX_FILES = 500;
const MAX_BYTES = 5 * 1024 * 1024;
const SKIP_DIRS = new Set(["node_modules", ".git", "dist", "build", "coverage"]);
const files = [];

function walk(directory) {
  for (const entry of readdirSync(directory, { withFileTypes: true })) {
    if (files.length > MAX_FILES) return;
    if (entry.name.startsWith(".") && entry.name !== ".github") continue;
    const absolute = join(directory, entry.name);
    if (entry.isDirectory()) {
      if (SKIP_DIRS.has(entry.name)) continue;
      walk(absolute);
    } else if (entry.isFile()) {
      files.push(absolute);
    }
  }
}
walk(root);

let strip;
try {
  ({ stripTypeScriptTypes: strip } = await import("node:module"));
} catch {
  strip = undefined;
}

const errors = [];
let checked = 0;
let totalBytes = 0;
for (const file of files) {
  const name = relative(root, file).replaceAll("\\\\", "/");
  const extension = extname(file).toLowerCase();
  if (![".ts", ".tsx", ".mts", ".cts", ".js", ".mjs", ".cjs", ".json"].includes(extension)) continue;
  const source = readFileSync(file);
  totalBytes += source.byteLength;
  if (totalBytes > MAX_BYTES) {
    errors.push({ file: name, error: "workspace_exceeds_verification_budget" });
    break;
  }
  const text = source.toString("utf8");
  checked += 1;
  if (extension === ".json") {
    try { JSON.parse(text); } catch (error) { errors.push({ file: name, error: "invalid_json: " + (error instanceof Error ? error.message : "parse_error") }); }
    continue;
  }
  if ([".ts", ".tsx", ".mts", ".cts"].includes(extension)) {
    if (typeof strip !== "function") {
      errors.push({ file: name, error: "typescript_validator_unavailable" });
      continue;
    }
    try {
      strip(text, { mode: "strip", sourceMap: false, sourceUrl: name });
    } catch (error) {
      errors.push({ file: name, error: "typescript_syntax_error: " + (error instanceof Error ? error.message.split("\\n")[0] : "parse_error") });
    }
    continue;
  }
  const result = spawnSync(process.execPath, ["--check", file], { encoding: "utf8", timeout: 20000 });
  if (result.status !== 0) {
    const detail = String(result.stderr ?? "").split("\\n").find((line) => line.trim().length > 0) ?? "syntax_error";
    errors.push({ file: name, error: "javascript_syntax_error: " + detail.slice(0, 300) });
  }
}

const report = { checked, files: files.length, errors, ok: errors.length === 0 };
process.stdout.write(JSON.stringify(report) + "\\n");
process.exit(report.ok ? 0 : 1);
`;
